<?php
function attendanceReport(array $u,array $filter):array{
 attRequire(attAccess($u));$from=$filter['from']??date('Y-m-d');$to=$filter['to']??$from;attRequire(dateValid($from)&&dateValid($to)&&$to>=$from&&(strtotime($to)-strtotime($from))<=366*86400,'Choose a report period of at most one year.');
 $existing=[];foreach(all('SELECT a.*,u.name AS recorded_staff FROM tutor_attendance a JOIN users u ON u.id=a.staff_id WHERE attendance_date>=? AND attendance_date<=?',[$from,$to])as $r)$existing[$r['timetable_id'].'|'.$r['attendance_date']]=$r;
 $rows=[];$settings=attSettings();foreach(scheduledRows()as $t){if(!($t['attendance_required']??1))continue;foreach(['department','programme','classroom_id','academic_year','semester']as $k)if(!empty($filter[$k])&&!sessionMatches($t,$k,(string)$filter[$k]))continue 2;
  for($d=new DateTimeImmutable($from);$d->format('Y-m-d')<=$to;$d=$d->modify('+1 day')){$day=$d->format('Y-m-d');$record=$existing[$t['id'].'|'.$day]??null;if(!$record&&!occurs($t,$day))continue;
   $own=teaching($u)&&((int)($record['staff_id']??0)===(int)$u['id']||scheduledFor($t,(int)$u['id'],$day));if(!attVisible($u,$t)&&!$own)continue;
   if(!empty($filter['staff_id'])&&(int)$filter['staff_id']!==(int)$t['staff_id']&&(int)$filter['staff_id']!==(int)($record['staff_id']??0)&&!scheduledFor($t,(int)$filter['staff_id'],$day))continue;
   $status=$record['attendance_status']??(time()>strtotime($day.' '.$t['start_time'])+$settings['close_minutes']*60?'Missed':'Upcoming');if(!empty($filter['status'])&&$filter['status']!==$status)continue;
   attRequire(count($rows)<50000,'This report exceeds 50,000 class occurrences. Select a shorter date range or filter by department.');$rows[]=['timetable_id'=>$t['id'],'date'=>$day,'tutor'=>$record['recorded_staff']??$t['name'],'subject'=>$t['subject_code'].' · '.$t['subject_name'],'department'=>sessionLabel($t,'department'),'programme'=>sessionLabel($t,'programme'),'room'=>$t['room_code'],'start'=>$t['start_time'],'end'=>$t['end_time'],'confirmed'=>$record['confirmed_at']??'','status'=>$status,'remarks'=>$record['remarks']??''];
  }
 }usort($rows,fn($a,$b)=>[$a['date'],$a['start'],$a['room']]<=>[$b['date'],$b['start'],$b['room']]);return $rows;
}
function adjustAttendance(array $u,array $p):void{
 attRequire(academic($u));attLock();$t=one('SELECT * FROM tutor_timetable WHERE id=?',[(int)($p['timetable_id']??0)]);$day=required($p,'day');attRequire($t&&($t['attendance_required']??1)&&occurs($t,$day),'No scheduled class on that date.');attRequire($day<=date('Y-m-d')||($p['status']??'')==='Cancelled','Future classes may only be cancelled.');$status=required($p,'status');attRequire(in_array($status,['Present','Late','Missed','Cancelled','Substituted','Adjusted']),'Invalid attendance status.');$note=required($p,'remarks');$staff=(int)$t['staff_id'];if($status==='Substituted'){$s=one('SELECT * FROM users WHERE id=?',[(int)($p['substitute_id']??0)]);attRequire($s&&teaching($s),'Select an authorized substitute tutor.');$staff=(int)$s['id'];}
 $old=one('SELECT * FROM tutor_attendance WHERE timetable_id=? AND attendance_date=?',[$t['id'],$day]);if($old)q('UPDATE tutor_attendance SET staff_id=?,attendance_status=?,remarks=?,updated_at=? WHERE id=?',[$staff,$status,$note,now(),$old['id']]);else q('INSERT INTO tutor_attendance(timetable_id,staff_id,classroom_id,attendance_date,scheduled_start,scheduled_end,attendance_status,ip_address,user_agent,remarks,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$t['id'],$staff,$t['classroom_id'],$day,$t['start_time'],$t['end_time'],$status,$_SERVER['REMOTE_ADDR']??'CLI','Admin adjustment',$note,now(),now()]);attAudit((int)$u['id'],'Attendance adjusted',(int)$t['id'],['date'=>$day,'before'=>$old?:null,'status'=>$status,'remarks'=>$note]);
}
